module uart_frame_tx$CLK_DIV_972 (
  input wire clk,
  input wire rst_n,
  input wire [15:0] div,
  input wire [3:0] cfg_data_bits,
  input wire [2:0] cfg_parity,
  input wire [1:0] cfg_stop,
  input wire [7:0] tx_data,
  input wire tx_valid,
  output wire tx_ready,
  output wire tx
);
  parameter CLK_DIV = 32'sh000003cc;
  parameter DIV_MIN = 16'h0004;
  parameter P_NONE = 3'h0;
  parameter P_ODD = 3'h1;
  parameter P_EVEN = 3'h2;
  parameter P_MARK = 3'h3;
  parameter P_SPACE = 3'h4;
  wire [15:0] div_used;
  wire [3:0] bits_used;
  wire par_en;
  wire two_stop;
  reg [7:0] dat;
  reg par_bit;
  reg [11:0] load;
  wire [3:0] frame_bits;
  reg [11:0] shift_q;
  reg [3:0] bit_cnt;
  reg [15:0] div_cnt;
  reg [15:0] div_last;
  reg [3:0] frame_last;
  reg busy_q;
  assign div_used = (div < 16'h0004) ? 16'h03cc : div;
  assign bits_used = ((cfg_data_bits >= 4'h5) && (cfg_data_bits <= 4'h8)) ? cfg_data_bits : 4'h8;
  assign par_en = (cfg_parity == 3'h1) | (cfg_parity == 3'h2) | (cfg_parity == 3'h3) | (cfg_parity == 3'h4);
  assign two_stop = cfg_stop != 2'h0;
  assign frame_bits = bits_used + 4'h2 + {3'h0, par_en} + {3'h0, two_stop};
  assign tx_ready = !busy_q;
  assign tx = shift_q[0];
  always @* begin
    case (bits_used)
      4'h5: begin
        dat = {3'h0, tx_data[4:0]};
      end
      4'h6: begin
        dat = {2'h0, tx_data[5:0]};
      end
      4'h7: begin
        dat = {1'b0, tx_data[6:0]};
      end
      default: begin
        dat = tx_data;
      end
    endcase
  end
  always @* begin
    case (cfg_parity)
      3'h1: begin
        par_bit = ~(^dat);
      end
      3'h2: begin
        par_bit = ^dat;
      end
      3'h4: begin
        par_bit = 1'b0;
      end
      default: begin
        par_bit = 1'b1;
      end
    endcase
  end
  always @* begin
    case (bits_used)
      4'h5: begin
        load = {5'h1f, par_bit, dat[4:0], 1'b0};
      end
      4'h6: begin
        load = {4'hf, par_bit, dat[5:0], 1'b0};
      end
      4'h7: begin
        load = {3'h7, par_bit, dat[6:0], 1'b0};
      end
      default: begin
        load = {2'h3, par_bit, dat[7:0], 1'b0};
      end
    endcase
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      shift_q <= 12'hfff;
      bit_cnt <= 4'h0;
      div_cnt <= 16'h0000;
      div_last <= 16'h03cb;
      frame_last <= 4'h9;
      busy_q <= 1'b0;
    end else if (!busy_q) begin
      div_cnt <= 16'h0000;
      bit_cnt <= 4'h0;
      if (tx_valid) begin
        shift_q <= load;
        busy_q <= 1'b1;
        div_last <= div_used - 16'h0001;
        frame_last <= frame_bits - 4'h1;
      end else begin
        shift_q <= 12'hfff;
      end
    end else if (div_cnt == div_last) begin
      div_cnt <= 16'h0000;
      shift_q <= {1'b1, shift_q[11:1]};
      bit_cnt <= bit_cnt + 4'h1;
      if (bit_cnt == frame_last) begin
        busy_q <= 1'b0;
      end
    end else begin
      div_cnt <= div_cnt + 16'h0001;
    end
  end
endmodule

