  parameter P_ODD = 3'h1;
  parameter P_EVEN = 3'h2;
  parameter P_MARK = 3'h3;
  parameter P_SPACE = 3'h4;
  parameter S_IDLE = 3'h0;
  parameter S_START = 3'h1;
  parameter S_DATA = 3'h2;
  parameter S_PARITY = 3'h3;
  parameter S_STOP = 3'h4;
  parameter S_BREAK = 3'h5;
