  reg rx_sync_q;
  reg [2:0] state;
  reg [15:0] div_cnt;
  reg [15:0] div_last;
  reg [15:0] div_half;
  reg par_got;
  reg [2:0] bit_idx;
  reg [7:0] shift_q;
  wire [1:0] amt;
  wire [7:0] align1;
  wire [7:0] aligned;
