  reg par_exp;
  wire frame_bad;
  wire par_bad;
  wire all_low;
  assign div_used = (div < 16'h0004) ? 16'h03cc : div;
  assign bits_used = ((cfg_data_bits >= 4'h5) && (cfg_data_bits <= 4'h8)) ? cfg_data_bits : 4'h8;
  assign amt = ~last_idx[1:0];
  assign align1 = amt[0] ? {1'b0, shift_q[7:1]} : shift_q;
  assign aligned = amt[1] ? {2'h0, align1[7:2]} : align1;
  assign par_en = (cfg_parity == 3'h1) | (cfg_parity == 3'h2) | (cfg_parity == 3'h3) | (cfg_parity == 3'h4);
  assign frame_bad = !rx_sync_q;
  assign par_bad = par_en & (par_got != par_exp);
  assign all_low = (aligned == 8'h00) & ((~par_en) | (~par_got));
  always @* begin
    case (bits_used)
      4'h5: begin
        last_idx = 3'h4;
      end
      4'h6: begin
        last_idx = 3'h5;
      end
      4'h7: begin
        last_idx = 3'h6;
      end
      default: begin
        last_idx = 3'h7;
      end
    endcase
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rx_meta_q <= 1'b1;
      rx_sync_q <= 1'b1;
    end else begin
      rx_meta_q <= rx;
      rx_sync_q <= rx_meta_q;
    end
  end
  always @* begin
    case (cfg_parity)
      3'h1: begin
        par_exp = ~(^aligned);
      end
      3'h2: begin
        par_exp = ^aligned;
      end
      3'h4: begin
        par_exp = 1'b0;
      end
      default: begin
        par_exp = 1'b1;
      end
    endcase
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= 3'h0;
      div_cnt <= 16'h0000;
      div_last <= 16'h03cb;
      div_half <= 16'h01e5;
      par_got <= 1'b0;
      bit_idx <= 3'h0;
      shift_q <= 8'h00;
      rx_data <= 8'h00;
      rx_valid <= 1'b0;
      rx_frame_error <= 1'b0;
      rx_parity_error <= 1'b0;
      rx_break <= 1'b0;
      rx_overrun <= 1'b0;
    end else begin
      rx_break <= 1'b0;
      rx_overrun <= 1'b0;
      if (rx_valid & rx_ready) begin
        rx_valid <= 1'b0;
        rx_frame_error <= 1'b0;
        rx_parity_error <= 1'b0;
      end
      case (state)
        3'h0: begin
          div_cnt <= 16'h0000;
          bit_idx <= 3'h0;
          if (!rx_sync_q) begin
            state <= 3'h1;
            div_last <= div_used - 16'h0001;
            div_half <= {1'b0, div_used[15:1]} - 16'h0001;
          end
        end
        3'h1: begin
          if (div_cnt == div_half) begin
            div_cnt <= 16'h0000;
            state <= rx_sync_q ? 3'h0 : 3'h2;
          end else begin
            div_cnt <= div_cnt + 16'h0001;
          end
        end
        3'h2: begin
          if (div_cnt == div_last) begin
            div_cnt <= 16'h0000;
            shift_q <= {rx_sync_q, shift_q[7:1]};
            if (bit_idx == last_idx) begin
              state <= par_en ? 3'h3 : 3'h4;
            end else begin
              bit_idx <= bit_idx + 3'h1;
            end
          end else begin
            div_cnt <= div_cnt + 16'h0001;
          end
        end
        3'h3: begin
          if (div_cnt == div_last) begin
            div_cnt <= 16'h0000;
            par_got <= rx_sync_q;
            state <= 3'h4;
          end else begin
            div_cnt <= div_cnt + 16'h0001;
          end
        end
        3'h4: begin
          if (div_cnt == div_last) begin
            div_cnt <= 16'h0000;
            if (frame_bad & all_low) begin
              rx_break <= 1'b1;
              state <= 3'h5;
            end else begin
              rx_data <= aligned;
              rx_valid <= 1'b1;
              rx_frame_error <= frame_bad;
              rx_parity_error <= par_bad;
              rx_overrun <= rx_valid & (~rx_ready);
              state <= 3'h0;
            end
          end else begin
            div_cnt <= div_cnt + 16'h0001;
          end
        end
        3'h5: begin
          div_cnt <= 16'h0000;
          if (rx_sync_q) begin
            state <= 3'h0;
          end
        end
        default: begin
          state <= 3'h0;
        end
      endcase
    end
  end
endmodule

