    .CLR(\core.rst_n$n ),
    .Q(\core.line.wt_last$ff$q23 )
  );
  LUT6 #(.INIT(64'h0000000000000000)) const0$lut (
    .I0(1'b0),
    .I1(1'b0),
    .I2(1'b0),
    .I3(1'b0),
    .I4(1'b0),
    .I5(1'b0),
    .O(const0)
  );
  LUT6 #(.INIT(64'hffffffffffffffff)) const1$lut (
    .I0(1'b0),
    .I1(1'b0),
    .I2(1'b0),
    .I3(1'b0),
    .I4(1'b0),
    .I5(1'b0),
    .O(const1)
  );
endmodule

module uart_frame_tx$CLK_DIV_16 (
  input wire clk,
  input wire rst_n,
  input wire [15:0] div,
  input wire [3:0] cfg_data_bits,
  input wire [2:0] cfg_parity,
  input wire [1:0] cfg_stop,
  input wire [7:0] tx_data,
  input wire tx_valid,
  output wire tx_ready,
  output wire tx
);
  parameter CLK_DIV = 32'sh00000010;
  parameter DIV_MIN = 16'h0004;
  parameter P_NONE = 3'h0;
  parameter P_ODD = 3'h1;
  parameter P_EVEN = 3'h2;
  parameter P_MARK = 3'h3;
  parameter P_SPACE = 3'h4;
  wire [15:0] div_used;
  wire [3:0] bits_used;
  wire par_en;
  wire two_stop;
  reg [7:0] dat;
  reg par_bit;
  reg [11:0] load;
  wire [3:0] frame_bits;
  reg [11:0] shift_q;
  reg [3:0] bit_cnt;
  reg [15:0] div_cnt;
  reg [15:0] div_last;
  reg [3:0] frame_last;
  reg busy_q;
  assign div_used = (div < 16'h0004) ? 16'h0010 : div;
  assign bits_used = ((cfg_data_bits >= 4'h5) && (cfg_data_bits <= 4'h8)) ? cfg_data_bits : 4'h8;
  assign par_en = (cfg_parity == 3'h1) | (cfg_parity == 3'h2) | (cfg_parity == 3'h3) | (cfg_parity == 3'h4);
  assign two_stop = cfg_stop != 2'h0;
  assign frame_bits = bits_used + 4'h2 + {3'h0, par_en} + {3'h0, two_stop};
  assign tx_ready = !busy_q;
  assign tx = shift_q[0];
  always @* begin
    case (bits_used)
      4'h5: begin
        dat = {3'h0, tx_data[4:0]};
      end
      4'h6: begin
        dat = {2'h0, tx_data[5:0]};
      end
      4'h7: begin
        dat = {1'b0, tx_data[6:0]};
      end
      default: begin
        dat = tx_data;
      end
    endcase
  end
  always @* begin
    case (cfg_parity)
      3'h1: begin
        par_bit = ~(^dat);
      end
      3'h2: begin
        par_bit = ^dat;
      end
      3'h4: begin
        par_bit = 1'b0;
      end
      default: begin
        par_bit = 1'b1;
      end
    endcase
  end
  always @* begin
    case (bits_used)
      4'h5: begin
        load = {5'h1f, par_bit, dat[4:0], 1'b0};
      end
      4'h6: begin
        load = {4'hf, par_bit, dat[5:0], 1'b0};
      end
      4'h7: begin
        load = {3'h7, par_bit, dat[6:0], 1'b0};
      end
      default: begin
        load = {2'h3, par_bit, dat[7:0], 1'b0};
      end
    endcase
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      shift_q <= 12'hfff;
      bit_cnt <= 4'h0;
      div_cnt <= 16'h0000;
      div_last <= 16'h000f;
      frame_last <= 4'h9;
      busy_q <= 1'b0;
    end else if (!busy_q) begin
      div_cnt <= 16'h0000;
      bit_cnt <= 4'h0;
      if (tx_valid) begin
        shift_q <= load;
        busy_q <= 1'b1;
        div_last <= div_used - 16'h0001;
        frame_last <= frame_bits - 4'h1;
      end else begin
        shift_q <= 12'hfff;
      end
    end else if (div_cnt == div_last) begin
      div_cnt <= 16'h0000;
      shift_q <= {1'b1, shift_q[11:1]};
      bit_cnt <= bit_cnt + 4'h1;
      if (bit_cnt == frame_last) begin
        busy_q <= 1'b0;
      end
    end else begin
      div_cnt <= div_cnt + 16'h0001;
    end
  end
endmodule

module uart_frame_rx$CLK_DIV_16 (
  input wire clk,
  input wire rst_n,
  input wire [15:0] div,
  input wire [3:0] cfg_data_bits,
  input wire [2:0] cfg_parity,
  input wire rx,
  input wire rx_ready,
  output reg [7:0] rx_data,
  output reg rx_valid,
  output reg rx_frame_error,
  output reg rx_parity_error,
  output reg rx_break,
  output reg rx_overrun
);
  parameter CLK_DIV = 32'sh00000010;
  parameter DIV_MIN = 16'h0004;
  parameter P_NONE = 3'h0;
  parameter P_ODD = 3'h1;
  parameter P_EVEN = 3'h2;
  parameter P_MARK = 3'h3;
  parameter P_SPACE = 3'h4;
  parameter S_IDLE = 3'h0;
  parameter S_START = 3'h1;
  parameter S_DATA = 3'h2;
  parameter S_PARITY = 3'h3;
  parameter S_STOP = 3'h4;
  parameter S_BREAK = 3'h5;
  wire [15:0] div_used;
  wire [3:0] bits_used;
  reg [2:0] last_idx;
  reg rx_meta_q;
  reg rx_sync_q;
  reg [2:0] state;
  reg [15:0] div_cnt;
  reg [15:0] div_last;
  reg [15:0] div_half;
  reg par_got;
  reg [2:0] bit_idx;
  reg [7:0] shift_q;
  wire [1:0] amt;
  wire [7:0] align1;
  wire [7:0] aligned;
  wire par_en;
  reg par_exp;
  wire frame_bad;
  wire par_bad;
  wire all_low;
  assign div_used = (div < 16'h0004) ? 16'h0010 : div;
  assign bits_used = ((cfg_data_bits >= 4'h5) && (cfg_data_bits <= 4'h8)) ? cfg_data_bits : 4'h8;
  assign amt = ~last_idx[1:0];
  assign align1 = amt[0] ? {1'b0, shift_q[7:1]} : shift_q;
  assign aligned = amt[1] ? {2'h0, align1[7:2]} : align1;
  assign par_en = (cfg_parity == 3'h1) | (cfg_parity == 3'h2) | (cfg_parity == 3'h3) | (cfg_parity == 3'h4);
  assign frame_bad = !rx_sync_q;
  assign par_bad = par_en & (par_got != par_exp);
  assign all_low = (aligned == 8'h00) & ((~par_en) | (~par_got));
  always @* begin
    case (bits_used)
      4'h5: begin
        last_idx = 3'h4;
      end
      4'h6: begin
        last_idx = 3'h5;
      end
      4'h7: begin
        last_idx = 3'h6;
      end
      default: begin
        last_idx = 3'h7;
      end
    endcase
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rx_meta_q <= 1'b1;
      rx_sync_q <= 1'b1;
    end else begin
      rx_meta_q <= rx;
      rx_sync_q <= rx_meta_q;
    end
  end
  always @* begin
    case (cfg_parity)
      3'h1: begin
        par_exp = ~(^aligned);
      end
      3'h2: begin
        par_exp = ^aligned;
      end
      3'h4: begin
        par_exp = 1'b0;
      end
      default: begin
        par_exp = 1'b1;
      end
    endcase
  end
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= 3'h0;
      div_cnt <= 16'h0000;
      div_last <= 16'h000f;
      div_half <= 16'h0007;
      par_got <= 1'b0;
      bit_idx <= 3'h0;
      shift_q <= 8'h00;
      rx_data <= 8'h00;
      rx_valid <= 1'b0;
      rx_frame_error <= 1'b0;
      rx_parity_error <= 1'b0;
      rx_break <= 1'b0;
      rx_overrun <= 1'b0;
    end else begin
      rx_break <= 1'b0;
      rx_overrun <= 1'b0;
      if (rx_valid & rx_ready) begin
        rx_valid <= 1'b0;
        rx_frame_error <= 1'b0;
        rx_parity_error <= 1'b0;
      end
      case (state)
        3'h0: begin
          div_cnt <= 16'h0000;
          bit_idx <= 3'h0;
          if (!rx_sync_q) begin
            state <= 3'h1;
            div_last <= div_used - 16'h0001;
            div_half <= {1'b0, div_used[15:1]} - 16'h0001;
          end
        end
        3'h1: begin
          if (div_cnt == div_half) begin
            div_cnt <= 16'h0000;
            state <= rx_sync_q ? 3'h0 : 3'h2;
          end else begin
            div_cnt <= div_cnt + 16'h0001;
          end
        end
        3'h2: begin
          if (div_cnt == div_last) begin
            div_cnt <= 16'h0000;
            shift_q <= {rx_sync_q, shift_q[7:1]};
            if (bit_idx == last_idx) begin
              state <= par_en ? 3'h3 : 3'h4;
            end else begin
              bit_idx <= bit_idx + 3'h1;
            end
          end else begin
            div_cnt <= div_cnt + 16'h0001;
          end
        end
        3'h3: begin
          if (div_cnt == div_last) begin
            div_cnt <= 16'h0000;
            par_got <= rx_sync_q;
            state <= 3'h4;
          end else begin
            div_cnt <= div_cnt + 16'h0001;
          end
        end
        3'h4: begin
          if (div_cnt == div_last) begin
            div_cnt <= 16'h0000;
            if (frame_bad & all_low) begin
              rx_break <= 1'b1;
              state <= 3'h5;
            end else begin
              rx_data <= aligned;
              rx_valid <= 1'b1;
              rx_frame_error <= frame_bad;
              rx_parity_error <= par_bad;
              rx_overrun <= rx_valid & (~rx_ready);
              state <= 3'h0;
            end
          end else begin
            div_cnt <= div_cnt + 16'h0001;
          end
        end
        3'h5: begin
          div_cnt <= 16'h0000;
          if (rx_sync_q) begin
            state <= 3'h0;
          end
        end
        default: begin
          state <= 3'h0;
        end
      endcase
    end
  end
endmodule

module uart_frame (
  input wire clk,
  input wire rst_n,
  input wire [15:0] div,
  input wire [3:0] cfg_data_bits,
  input wire [2:0] cfg_parity,
  input wire [1:0] cfg_stop,
  input wire [7:0] tx_data,
  input wire tx_valid,
  output wire tx_ready,
  output wire tx,
  input wire rx,
  input wire rx_ready,
  output wire [7:0] rx_data,
  output wire rx_valid,
  output wire rx_frame_error,
  output wire rx_parity_error,
  output wire rx_break,
  output wire rx_overrun
);
  parameter CLK_DIV = 32'sh00000010;
  uart_frame_tx$CLK_DIV_16 u_tx (
    .clk(clk),
    .rst_n(rst_n),
    .div(div),
    .cfg_data_bits(cfg_data_bits),
    .cfg_parity(cfg_parity),
    .cfg_stop(cfg_stop),
    .tx_data(tx_data),
    .tx_valid(tx_valid),
    .tx_ready(tx_ready),
    .tx(tx)
  );
  uart_frame_rx$CLK_DIV_16 u_rx (
    .clk(clk),
    .rst_n(rst_n),
    .div(div),
    .cfg_data_bits(cfg_data_bits),
    .cfg_parity(cfg_parity),
    .rx(rx),
    .rx_ready(rx_ready),
    .rx_data(rx_data),
    .rx_valid(rx_valid),
    .rx_frame_error(rx_frame_error),
    .rx_parity_error(rx_parity_error),
    .rx_break(rx_break),
    .rx_overrun(rx_overrun)
  );
endmodule

module uart_baud_div (
  input wire clk,
  input wire rst_n,
  input wire [31:0] rate,
  output reg [15:0] div,
  output reg ok,
  output reg busy
);
  parameter CLK_HZ = 32'h03938700;
  parameter DIV_RESET = 16'h0209;
  parameter DIV_MIN = 16'h001e;
  parameter LAST_STEP = 5'h1f;
  reg [31:0] num;
  reg [32:0] rem;
  reg [31:0] quo;
  reg [31:0] den;
  reg [4:0] step;
  reg [31:0] seen;
  wire [32:0] shifted;
  wire fits;
  wire [32:0] next;
  wire fits_16;
  wire big_enough;
  assign shifted = {rem[31:0], num[31]};
  assign fits = shifted >= {1'b0, den};
  assign next = fits ? (shifted - {1'b0, den}) : shifted;
  assign fits_16 = quo[31:16] == 16'h0000;
  assign big_enough = quo[15:0] >= 16'h001e;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      div <= 16'h0209;
      ok <= 1'b0;
      busy <= 1'b0;
      num <= 32'h00000000;
      rem <= 33'h000000000;
      quo <= 32'h00000000;
      den <= 32'h00000000;
      step <= 5'h00;
      seen <= 32'h00000000;
    end else if (busy) begin
      rem <= next;
      num <= {num[30:0], 1'b0};
      quo <= {quo[30:0], fits};
      step <= step + 5'h01;
      if (step == 5'h1f) begin
        busy <= 1'b0;
      end
    end else if (seen != rate) begin
      seen <= rate;
      if (rate == 32'h00000000) begin
        div <= 16'h0209;
        ok <= 1'b0;
      end else begin
        num <= 32'h03938700 + {1'b0, rate[31:1]};
        den <= rate;
        rem <= 33'h000000000;
        quo <= 32'h00000000;
        step <= 5'h00;
        busy <= 1'b1;
      end
    end else if (fits_16 && big_enough) begin
      div <= quo[15:0];
      ok <= 1'b1;
    end else begin
      div <= 16'h0209;
      ok <= 1'b0;
    end
  end
endmodule

module uart_line_coding (
  input wire [7:0] char_format,
  input wire [7:0] parity,
  input wire [7:0] data_bits,
  output wire [3:0] cfg_data_bits,
  output wire [2:0] cfg_parity,
  output wire [1:0] cfg_stop,
  output wire ok
);
  wire bits_ok;
  wire par_ok;
  wire fmt_ok;
  assign bits_ok = (data_bits >= 8'h05) && (data_bits <= 8'h08);
  assign par_ok = parity <= 8'h04;
  assign fmt_ok = (char_format == 8'h00) || (char_format == 8'h02);
  assign cfg_data_bits = bits_ok ? data_bits[3:0] : 4'h8;
  assign cfg_parity = par_ok ? parity[2:0] : 3'h0;
  assign cfg_stop = ((char_format == 8'h01) || (char_format == 8'h02)) ? 2'h2 : 2'h0;
  assign ok = bits_ok & par_ok & fmt_ok;
endmodule
